-- Row count and content digest of every Expansion table and the migration journals (read-only).
DO $$
DECLARE r record; c bigint; h text;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS snap(tbl text, n bigint, digest text);
  FOR r IN SELECT schemaname, tablename FROM pg_tables
           WHERE (schemaname = 'public' AND tablename LIKE 'expansion_%') OR (schemaname = 'drizzle')
           ORDER BY 1, 2 LOOP
    EXECUTE format('SELECT count(*), md5(coalesce(string_agg(t::text, ''|'' ORDER BY t::text), '''')) FROM %I.%I t', r.schemaname, r.tablename) INTO c, h;
    INSERT INTO snap VALUES (r.schemaname || '.' || r.tablename, c, h);
  END LOOP;
END $$;
SELECT tbl, n, digest FROM snap ORDER BY tbl;

